<script setup lang="ts">
import type { CalendarDetail } from '~/types/provenance'
import { eventTypeLabel, formatDate, validDate } from '~/utils/calendar'
import { verificationState } from '~/utils/provenance'
defineProps<{ event: CalendarDetail }>()
defineEmits<{ inspect: [id: string] }>()
</script>
<template><div class="provenance-stack"><header class="provenance-stack"><div class="provenance-meta"><UiBadge>{{ eventTypeLabel(event.event_type) }}</UiBadge><span v-if="event.region_code" class="muted">Регион {{ event.region_code }}</span></div><h1>{{ event.title }}</h1><p class="provenance-description">{{ event.description }}</p></header>
  <div class="provenance-columns"><UiCard><EventSourceList :sources="event.sources" @inspect="$emit('inspect', $event)" /></UiCard><aside class="provenance-stack"><UiCard class="provenance-checklist"><h2>Перед проведением</h2><ul><li>Сверьте дату и название с первоисточником.</li><li>Проверьте культурные сведения и конкретные цитаты.</li><li>Учитывайте возраст и регион.</li></ul></UiCard><UiCard class="provenance-stack"><h2>Даты проведения</h2><p v-if="event.date_type === 'fixed_annual' && event.fixed_month && event.fixed_day && validDate(`2000-${String(event.fixed_month).padStart(2,'0')}-${String(event.fixed_day).padStart(2,'0')}`)">Ежегодная дата: {{ formatDate(`2000-${String(event.fixed_month).padStart(2,'0')}-${String(event.fixed_day).padStart(2,'0')}`, { year: undefined }) }}</p><p v-for="row in event.occurrences" :key="row.id">{{ formatDate(row.start_date) }}<template v-if="row.end_date && row.end_date !== row.start_date"> — {{ formatDate(row.end_date) }}</template> · {{ row.academic_year }}<br>{{ row.source_reference || 'Ссылка на запись не указана' }}</p><p v-if="!event.occurrences?.length && !event.fixed_month">Дата проведения не указана в календаре.</p><p class="muted">Записи проведения относятся к конкретному учебному году. Перед мероприятием сверяйте анонс и источник.</p></UiCard></aside></div>
  <UiCard><section class="provenance-stack"><h2>Культурные утверждения</h2><p v-if="!event.cultural_claims.length" class="muted">Культурные утверждения не добавлены.</p><article v-for="claim in event.cultural_claims" :key="claim.id" class="provenance-source"><p class="provenance-eyebrow">{{ claim.culture_name }}</p><h3><NuxtLink :to="`/claims/${encodeURIComponent(claim.id)}`">{{ claim.claim_text }}</NuxtLink></h3><UiAlert v-if="!claim.evidence_records.length" tone="warning">Нет подтверждающих доказательств.</UiAlert><div v-for="(record, index) in claim.evidence_records" :key="`${record.event_source_id}:${index}`" class="evidence-record"><ProvenanceStatus :state="record.citation_locator?.trim() && record.citation_excerpt?.trim() ? verificationState(record.verification_status) : { label: 'Недостаточно доказательств', tone: 'warning' }" /><p>Локатор: {{ record.citation_locator || 'Не указан' }}</p><details><summary>Показать цитату</summary><blockquote>{{ record.citation_excerpt || 'Цитата отсутствует' }}</blockquote></details><NuxtLink :to="`/sources/${encodeURIComponent(record.event_source_id)}`">Открыть первоисточник</NuxtLink></div><NuxtLink :to="`/claims/${encodeURIComponent(claim.id)}`">Все доказательства и история изменений →</NuxtLink></article></section></UiCard>
</div></template>
